contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint amount) public payable {
        require(address(this).balance >= amount);

        bool success;
        if (caller == address(this)) {
            try c.sudicideAnyone{value: amount}() {
                success = true;
            } catch {
                success = false;
            }
            assert(success);
