contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        // The test contract is the owner of c, because it deployed c in its constructor.
        // Send some Ether to c so that we can observe the balance change.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }

