contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Record pre-call state.
        uint256 cBalBefore = address(c).balance;
        uint256 thisBalBefore = address(this).balance;

        // Try to fund c with the provided amount; only succeeds if owner (we are).
        // Use a low-level call so we can make it its own top-level statement.
        (bool funded, ) = address(c).call{value: amount}("");
        require(funded);

        // The deciding call: sudicideAnyone. We are the owner (deployer of c).
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }

        assert(!reverted);
        assert(address(this).balance == thisBalBefore + cBalBefore + amount);
    }

    receive() external payable {}
}

