    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "not enough balance");
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "pre-funding failed");
        require(address(c).balance == amount, "C balance mismatch");

        uint256 testBefore = address(this).balance;
        uint256 cBefore = address(c).balance;

        c.sudicideAnyone();

        uint256 testAfter = address(this).balance;
        uint256 cAfter = address(c).balance;

        assert(cAfter == 0 && testAfter == testBefore + cBefore);
    }

    receive() external payable {}
}

