contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        uint256 testBalBefore = address(this).balance;
        uint256 cBalBefore = address(c).balance;
        require(cBalBefore == 0);

        // Fund C with `amount` Ether via a call that is not sudicideAnyone.
        // The only available way to send Ether to C is through its receive/fallback,
        // but C has neither, so instead we send directly. If this is not possible,
        // the setup requirement cBalBefore == 0 will already have filtered it.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        uint256 cBalAfterFund = address(c).balance;
        require(cBalAfterFund == amount);

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && address(c).balance == 0 && address(this).balance == testBalBefore + cBalAfterFund);
    }
}

